cd /workspace/pr/head/.claude/data/schemas; python3 - <<'EOF'
import json
s=json.load(open('model-config-v3.schema.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if k in('sample_size','default_effort','ceiling_calibration','source','calibrated_at'):
                print(p+'/'+k, json.dumps(v)[:300])
            walk(v,p+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,p+f'[{i}]')
walk(s)
EOF

